const TALLERES_EVENTOS=[],ICAL_URL_YURTA1="https://www.airbnb.com/calendar/ical/1267620632342788641.ics?t=28be1aecaa5c4cb1b4213a716fd00a8d&locale=es-XL",ICAL_URL_YURTA2="https://www.airbnb.com/calendar/ical/47333689.ics?t=2c5799a6fea7496fa0030b5b3e5302bd&locale=es-XL",OCUPADOS_ICAL={yurta1:[],yurta2:[]},PRODUCTOS_BASE=[{id:1,nombre:"Aceite de Cannabis",categoria:"aceites",precio:450,descripcion:"Aceite macerado de caléndula, ideal para pieles sensibles y irritadas.",descripcionLarga:"Aceite elaborado artesanalmente mediante maceración lenta de flores de caléndula y cannabis en aceite de oliva orgánico, durante al menos 40 días al sol.\n\nEs un aceite nutritivo y calmante, ideal para pieles sensibles, irritadas o con tendencia a la sequedad. Ayuda a reducir inflamaciones, calmar rojeces y promover la regeneración natural de la piel.\n\nModo de uso: aplicar unas gotas sobre la zona deseada con un suave masaje, hasta que se absorba por completo. Puede usarse en rostro, cuerpo y manos.\n\nIngredientes: aceite de oliva orgánico, flores de caléndula, flores de cannabis, vitamina E natural.\n\nContenido: 30 ml.",imagen:"assets/images/productos/aceite-calendula.jpg",imagenes:["assets/images/productos/aceite-calendula.jpg","assets/images/productos/aceite-calendula-2.jpg","assets/images/productos/aceite-calendula-3.jpg"],stock:!1},{id:5,nombre:"Pomada de Caléndula & Cannabis",categoria:"pomadas",precio:380,descripcion:"Pomada cicatrizante con caléndula y propóleo, para heridas y rozaduras.",descripcionLarga:"Pomada artesanal elaborada con cera de abejas, manteca de karité, aceite de caléndula y extracto de cannabis. Enriquecida con propóleo, conocido por sus propiedades antibacterianas y regeneradoras.\n\nEs un bálsamo protector y cicatrizante, ideal para heridas leves, rozaduras, piel agrietada, eccemas y picaduras de insectos. Su textura es densa pero se funde al contacto con la piel.\n\nModo de uso: aplicar una capa fina sobre la zona limpia y seca, 2 a 3 veces por día.\n\nIngredientes: cera de abejas, manteca de karité, aceite de oliva, caléndula, cannabis, propóleo, vitamina E.\n\nContenido: 50 g.",imagen:"assets/images/productos/pomada-calendula.jpg",imagenes:["assets/images/productos/pomada-calendula.jpg","assets/images/productos/pomada-calendula-2.jpg","assets/images/productos/pomada-calendula-3.jpg"],stock:!0},{id:9,nombre:"Jabón artesanal de Cannabis · Milenrama · Marcela",categoria:"jabones",precio:280,descripcion:"Jabón artesanal con aceite de oliva y lavanda, suave y aromático.",descripcionLarga:"Jabón elaborado por saponificación en frío, con aceite de oliva orgánico como base principal. Combina cannabis, milenrama y marcela, tres plantas con propiedades calmantes y regeneradoras para la piel.\n\nSu espuma es cremosa y suave, ideal para pieles sensibles o con tendencia a la irritación. El aroma es herbal y fresco, con un toque floral aportado por la milenrama.\n\nModo de uso: frotar entre las manos húmedas hasta obtener espuma, aplicar sobre la piel y enjuagar con abundante agua.\n\nIngredientes: aceite de oliva, aceite de coco, manteca de karité, cannabis, milenrama, marcela, aceites esenciales.\n\nContenido: 100 g.",imagen:"assets/images/productos/jabon-lavanda.jpg",imagenes:["assets/images/productos/jabon-lavanda.jpg","assets/images/productos/jabon-lavanda-2.jpg","assets/images/productos/jabon-lavanda-3.jpg"],stock:!0},{id:13,nombre:"Tintura de MBURUCUYÁ",categoria:"tinturas",precio:320,descripcion:"Tintura madre de propóleo, antibacteriano y reforzador del sistema inmune.",descripcionLarga:"Tintura madre de mburucuyá (passiflora), elaborada a partir de hojas y flores frescas maceradas en alcohol de cereal. Es conocida por sus propiedades ansiolíticas y sedantes suaves.\n\nAyuda a calmar estados de nerviosismo, ansiedad leve y dificultades para dormir. También se utiliza como relajante natural en momentos de estrés.\n\nModo de uso: 20 a 30 gotas, 2 o 3 veces por día, diluidas en agua o infusión. Consultar con un profesional antes de su uso en embarazo o lactancia.\n\nIngredientes: hojas y flores de mburucuyá, alcohol de cereal 60°, agua purificada.\n\nContenido: 30 ml.",imagen:"assets/images/productos/tintura-mburucuya.jpg",imagenes:["assets/images/productos/tintura-mburucuya-1.jpg","assets/images/productos/tintura-mburucuya-2.jpg","assets/images/productos/tintura-mburucuya-3.jpg"],stock:!0},{id:14,nombre:"Tintura de MILENRAMA",categoria:"tinturas",precio:350,descripcion:"Tintura de equinácea para reforzar defensas.",descripcionLarga:"Tintura madre de milenrama (achillea millefolium), elaborada con flores frescas maceradas en alcohol de cereal. Es una planta tradicionalmente utilizada por sus propiedades antiinflamatorias y digestivas.\n\nAyuda a regular el ciclo menstrual, aliviar cólicos y mejorar la digestión. También se usa como tónico circulatorio y para calmar inflamaciones internas.\n\nModo de uso: 20 a 30 gotas, 2 veces por día, diluidas en agua. Consultar con un profesional antes de su uso prolongado.\n\nIngredientes: flores de milenrama, alcohol de cereal 60°, agua purificada.\n\nContenido: 30 ml.",imagen:"assets/images/productos/tintura-equipacea.jpg",imagenes:["assets/images/productos/tintura-equipacea.jpg","assets/images/productos/tintura-equipacea-2.jpg","assets/images/productos/tintura-equipacea-3.jpg"],stock:!0},{id:15,nombre:"Tintura de ARTEMISIA",categoria:"tinturas",precio:310,descripcion:"Tintura de ajo, antibiótico natural.",descripcionLarga:"Tintura madre de artemisia (ajenjo), elaborada con hojas frescas maceradas en alcohol de cereal. Es una planta amarga con propiedades digestivas, antiparasitarias y tónicas del sistema digestivo.\n\nTradicionalmente utilizada para estimular el apetito, mejorar digestiones pesadas y como apoyo en procesos de limpieza intestinal.\n\nModo de uso: 15 a 20 gotas, 2 veces por día, diluidas en agua, preferentemente antes de las comidas. Consultar con un profesional antes de su uso.\n\nIngredientes: hojas de artemisia, alcohol de cereal 60°, agua purificada.\n\nContenido: 30 ml.",imagen:"assets/images/productos/tintura-ajo.jpg",imagenes:["assets/images/productos/tintura-ajo.jpg","assets/images/productos/tintura-ajo-2.jpg","assets/images/productos/tintura-ajo-3.jpg"],stock:!1},{id:16,nombre:"Sahúmo de Salvia",categoria:"sahunos",precio:250,descripcion:"Sahúmo de salvia blanca para limpieza energética.",descripcionLarga:"Sahúmo artesanal de salvia blanca, atado a mano con hilo de algodón. La salvia blanca es una planta tradicionalmente utilizada por pueblos originarios para la limpieza energética de espacios y personas.\n\nSu humo se utiliza para purificar ambientes, disipar energías densas y preparar el espacio para la meditación o el trabajo espiritual.\n\nModo de uso: encender un extremo, apagar la llama y dejar que el humo se disperse por el ambiente. Apagar sobre un recipiente resistente al calor.\n\nContenido: 1 atado de aproximadamente 10 cm de largo.",imagen:"assets/images/productos/sahumo-salvia.jpg",imagenes:["assets/images/productos/sahumo-salvia.jpg","assets/images/productos/sahumo-salvia-2.jpg","assets/images/productos/sahumo-salvia-3.jpg"],stock:!0},{id:17,nombre:"Sahúmo de Palo Santo",categoria:"sahunos",precio:300,descripcion:"Palo Santo para aromaterapia y meditación.",descripcionLarga:"Sahúmo elaborado con astillas de palo santo (bursera graveolens), recolectadas de árboles caídos naturalmente. Su aroma es dulce, amaderado y ligeramente cítrico.\n\nEs utilizado para limpiar energías, atraer buenas vibras y crear un ambiente sereno. Ideal para meditación, yoga o simplemente para perfumar el hogar.\n\nModo de uso: encender un extremo, apagar la llama y dejar que el humo se disperse. Apagar sobre un recipiente resistente al calor.\n\nContenido: 1 atado de aproximadamente 10 cm de largo.",imagen:"assets/images/productos/sahumo-palo.jpg",imagenes:["assets/images/productos/sahumo-palo.jpg","assets/images/productos/sahumo-palo-2.jpg","assets/images/productos/sahumo-palo-3.jpg"],stock:!0},{id:18,nombre:"Sahúmo de Romero",categoria:"sahunos",precio:230,descripcion:"Sahúmo de romero para claridad mental.",descripcionLarga:"Sahúmo artesanal de romero, atado a mano con hilo de algodón. El romero es una planta asociada a la claridad mental, la memoria y la protección.\n\nSu humo se utiliza para limpiar el ambiente, estimular la concentración y renovar la energía de un espacio antes de estudiar o trabajar.\n\nModo de uso: encender un extremo, apagar la llama y dejar que el humo se disperse por el ambiente. Apagar sobre un recipiente resistente al calor.\n\nContenido: 1 atado de aproximadamente 10 cm de largo.",imagen:"assets/images/productos/sahumo-romero.jpg",imagenes:["assets/images/productos/sahumo-romero.jpg","assets/images/productos/sahumo-romero-2.jpg","assets/images/productos/sahumo-romero-3.jpg"],stock:!1},{id:19,nombre:"Manzanilla",categoria:"hierbas",precio:180,descripcion:"Flores de manzanilla secas, digestivas y relajantes.",descripcionLarga:"Flores de manzanilla (matricaria chamomilla) cultivadas en nuestra huerta agroecológica y secadas a baja temperatura para conservar sus propiedades.\n\nEs una planta suave, ideal para calmar el sistema digestivo y favorecer el descanso. Su infusión es aromática, ligeramente dulce y muy reconfortante.\n\nModo de uso: 1 cucharada por taza de agua caliente, dejar reposar 5 a 7 minutos, colar y beber. Se puede tomar hasta 3 veces por día.\n\nPresentación: bolsa de 30 g de flores secas.",imagen:"assets/images/productos/hierba-manzanilla.jpg",imagenes:["assets/images/productos/hierba-manzanilla.jpg","assets/images/productos/hierba-manzanilla-2.jpg","assets/images/productos/hierba-manzanilla-3.jpg"],stock:!0},{id:20,nombre:"Menta",categoria:"hierbas",precio:160,descripcion:"Hojas de menta secas, aromáticas y digestivas.",descripcionLarga:"Hojas de menta (mentha spicata) cultivadas sin agroquímicos y secadas a la sombra para preservar su aroma fresco y sus aceites esenciales.\n\nEs una planta refrescante y digestiva, ideal para después de las comidas. Su infusión ayuda a aliviar la pesadez estomacal y refrescar el aliento.\n\nModo de uso: 1 cucharada por taza de agua caliente, dejar reposar 5 minutos, colar y beber.\n\nPresentación: bolsa de 30 g de hojas secas.",imagen:"assets/images/productos/hierba-menta.jpg",imagenes:["assets/images/productos/hierba-menta.jpg","assets/images/productos/hierba-menta-2.jpg","assets/images/productos/hierba-menta-3.jpg"],stock:!0},{id:21,nombre:"Hipérico",categoria:"hierbas",precio:200,descripcion:"Planta de hipérico seca, para infusiones calmantes.",descripcionLarga:"Hipérico (hypericum perforatum) cultivado en nuestra huerta y secado a baja temperatura. Es una planta tradicionalmente utilizada por sus propiedades antidepresivas suaves y calmantes.\n\nSu infusión ayuda a mejorar el ánimo, reducir la ansiedad y favorecer un descanso reparador. Se recomienda consultar con un profesional antes de su uso prolongado.\n\nModo de uso: 1 cucharada por taza de agua caliente, dejar reposar 7 minutos, colar y beber, preferentemente por la noche.\n\nPresentación: bolsa de 30 g de planta seca.",imagen:"assets/images/productos/hierba-hiperico.jpg",imagenes:["assets/images/productos/hierba-hiperico.jpg","assets/images/productos/hierba-hiperico-2.jpg","assets/images/productos/hierba-hiperico-3.jpg"],stock:!1},{id:22,nombre:"Romero",categoria:"hierbas",precio:170,descripcion:"Romero seco, estimulante y antioxidante.",descripcionLarga:"Romero (rosmarinus officinalis) cultivado en nuestra huerta agroecológica, cosechado a mano y secado a la sombra.\n\nEs una planta estimulante y antioxidante, ideal para infusiones que ayudan a mejorar la concentración, la circulación y la digestión. Su aroma es intenso y resinoso.\n\nModo de uso: 1 cucharada por taza de agua caliente, dejar reposar 5 a 7 minutos, colar y beber.\n\nPresentación: bolsa de 30 g de hojas secas.",imagen:"assets/images/productos/hierba-romero.jpg",imagenes:["assets/images/productos/hierba-romero.jpg","assets/images/productos/hierba-romero-2.jpg","assets/images/productos/hierba-romero-3.jpg"],stock:!0},{id:23,nombre:"Semillas de Aromáticas (mix)",categoria:"semillas",precio:220,descripcion:"Mix de semillas de albahaca, perejil, cilantro y eneldo.",descripcionLarga:"Mix de semillas de aromáticas seleccionadas para huerta o maceta: albahaca, perejil, cilantro y eneldo. Todas variedades de fácil germinación y rápido crecimiento.\n\nIdeal para empezar tu propio huerto de aromáticas en casa, balcón o terraza. Cada sobre contiene semillas suficientes para una temporada completa.\n\nModo de uso: sembrar en sustrato fértil y húmedo, a 0,5 cm de profundidad, en un lugar con buena luz. Mantener húmedo hasta la germinación (7 a 14 días).\n\nContenido: sobre con mix de semillas para aproximadamente 20 plantas.",imagen:"assets/images/productos/semillas-aromaticas.jpg",imagenes:["assets/images/productos/semillas-aromaticas.jpg","assets/images/productos/semillas-aromaticas-2.jpg","assets/images/productos/semillas-aromaticas-3.jpg"],stock:!0},{id:24,nombre:"Plantín de Lavanda",categoria:"semillas",precio:350,descripcion:"Plantín de lavanda para tu jardín o maceta.",descripcionLarga:"Plantín de lavanda (lavandula angustifolia) cultivado en maceta de vivero, listo para trasplantar a jardín o maceta definitiva.\n\nEs una planta perenne, aromática y muy resistente. Sus flores atraen polinizadores y pueden usarse frescas o secas para sahumerios, infusiones y aromaterapia.\n\nModo de uso: trasplantar en un lugar con buena exposición solar y suelo bien drenado. Regar con moderación, evitando encharcamientos.\n\nPresentación: plantín en maceta de 10 cm de diámetro.",imagen:"assets/images/productos/plantin-lavanda.jpg",imagenes:["assets/images/productos/plantin-lavanda.jpg","assets/images/productos/plantin-lavanda-2.jpg","assets/images/productos/plantin-lavanda-3.jpg"],stock:!0},{id:25,nombre:"Semillas de Caléndula",categoria:"semillas",precio:190,descripcion:"Semillas de caléndula, flor medicinal y ornamental.",descripcionLarga:"Semillas de caléndula (calendula officinalis), flor medicinal y ornamental de fácil cultivo. Florece durante gran parte del año y atrae abejas y mariposas al jardín.\n\nSus flores pueden usarse frescas o secas para elaborar aceites, pomadas e infusiones con propiedades calmantes y regeneradoras de la piel.\n\nModo de uso: sembrar directamente en tierra o maceta, a 1 cm de profundidad, en un lugar con buena luz. Germina en 7 a 14 días.\n\nContenido: sobre con aproximadamente 30 semillas.",imagen:"assets/images/productos/semillas-calendula.jpg",imagenes:["assets/images/productos/semillas-calendula.jpg","assets/images/productos/semillas-calendula-2.jpg","assets/images/productos/semillas-calendula-3.jpg"],stock:!1},{id:26,nombre:"Plantín de Romero",categoria:"semillas",precio:320,descripcion:"Plantín de romero para cultivar en casa.",descripcionLarga:"Plantín de romero (rosmarinus officinalis) cultivado en maceta de vivero, listo para trasplantar a jardín, huerta o maceta definitiva.\n\nEs una planta perenne, aromática y muy resistente, ideal para huertas urbanas y jardines de bajo mantenimiento. Puede usarse en la cocina, para infusiones o como planta ornamental.\n\nModo de uso: trasplantar en un lugar con buena exposición solar y suelo bien drenado. Regar con moderación, evitando encharcamientos.\n\nPresentación: plantín en maceta de 10 cm de diámetro.",imagen:"assets/images/productos/plantin-romero.jpg",imagenes:["assets/images/productos/plantin-romero.jpg","assets/images/productos/plantin-romero-2.jpg","assets/images/productos/plantin-romero-3.jpg"],stock:!0}],filtros={categoria:"todos",texto:"",orden:"relevancia"};let carrito=[],productosAdmin=[],adminLogueado=!1,productoEditando=null;const MESES=["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"],DIAS_SEMANA=["Lu","Ma","Mi","Ju","Vi","Sá","Do"],NOMBRES_YURTAS={1:"Yurta Ceibo",2:"Yurta Canelón"},ADMIN